        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from address, caddress (we'll supply a helper address if needed), array of tos, and value v
    function testFuzz_property(address from, address /*unused_caddr*/, address[] memory _tos, uint256 v) public {
        // admissible domain: require non-empty tos to satisfy the contract's require(_tos.length > 0)
        vm.assume(_tos.length > 0);

        // We need a callee with code because calling a plain EOA always succeeds; deploy a minimal callee
        Adversary adv = new Adversary();

        // Make the call via try/catch to capture the return boolean of an external low-level call to c.transfer
        bool ok;
        // call transfer on c with our adversarial callee address; the reference returns true for all admissible inputs
        try c.transfer(from, address(adv), _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // transfer should not revert for admissible inputs; if it reverts treat as failure
            ok = false;
        }

        // The general property: reference contract always returns true for any admissible inputs
        assertTrue(ok);
    }
}

// Minimal adversarial callee: accepts any call and returns normally (so low-level call succeeds)
contract Adversary {
    // provide a fallback that accepts any calldata and returns empty success
    fallback() external payable {
        // do nothing, succeed
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: from address, amount v (uint), and an array length to build _tos
    // we pass a helper contract address as the caddress by deploying it here (adversarial callee)
    function testFuzz_property(address from, uint256 v, uint16 tosLen) public {
        // keep tosLen in a reasonable but wide bound (0..10). Must be >0 to satisfy require in transfer.
        tosLen = uint16(bound(tosLen, 1, 10));

        // deploy a helper that will fail on calls to transferFrom for at least one of the recipients
        FailingCallee failer = new FailingCallee();

        // build _tos array of addresses — use the failer address as one element to trigger failing external call
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) {
            // put the failing callee at position 0 and arbitrary (EOA) addresses elsewhere
            if (i == 0) tos[i] = address(failer);
            else tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, v, i)))));
        }

        // Call c.transfer and observe whether it returns or reverts. The property we assert is:
        // The reference contract never returns false; it always returns true (if it doesn't revert).
        // We therefore assert that the call does not return false. We capture the boolean return via try/catch.

        bool ok;
        try c.transfer(from, address(failer), tos, v) returns (bool ret) {
            ok = ret; // should be true for the reference implementation for all inputs
        } catch {
            // if it reverts, treat as not-ok (but reference should not revert for these inputs)
            ok = false;
        }

        // Single assertion: reference C satisfies that returned bool is true for all admissible inputs;
        // the mutant which returns false on failed external calls will fail this assertion for some inputs
        assertTrue(ok);
    }
}

// Adversarial helper: any low-level call to transferFrom will fail (return false / revert).
contract FailingCallee {
    // match selector transferFrom(address,address,uint256) fallback will revert to simulate failure
    fallback() external payable {
        revert("fail");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // helper that accepts arbitrary low-level calls and returns success (does nothing)
    // not strictly necessary for success-succeeding callees (EOAs would also succeed),
    // but we provide it to be a realistic callee with code so fuzzed address won't be an empty EOA.
    Receiver r;

    function setUp() public { 
        c = new C();
        r = new Receiver();
    }

    // fuzzed inputs: an address 'from', an address to use as caddress (we'll pass receiver's address to ensure code),
    // a uint256 lengthSeed used to build an array length (we must supply an array to the call), and a uint value v
    function testFuzz_property(address from, uint256 lengthSeed, uint256 v) public {
        // keep length reasonably bounded but allow 0..10 to cover zero and single and multi lengths
        uint256 len = bound(lengthSeed, 0, 10);

        // build _tos array of addresses; use r (contract with code) for each element to ensure the low-level call targets an address with code
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(r);
        }

        // admissible domain: require non-empty as the function requires _tos.length > 0
        vm.assume(len > 0);

        // call transfer and capture whether it returns (ok==true) or reverts (ok==false)
        bool ok;
        try c.transfer(from, address(r), tos, v) returns (bool ret) {
            // record whether it returned true
            ok = ret;
        } catch {
            ok = false;
        }

        // General property: for any non-empty _tos, the reference implementation returns true (so ok must be true).
        // The mutant returns false whenever _tos.length == 1, so for len == 1 the mutant will make this assertion fail.
        assertTrue(ok);
    }
}

// Minimal receiver that accepts arbitrary calls and does nothing (succeeds)
contract Receiver {
    fallback() external payable {
        // do nothing, succeed
    }
    receive() external payable {}
}
